package com.bridge.quartercore;
import org.junit.jupiter.api.Test;import java.time.*;import java.util.*;import java.util.concurrent.atomic.*;
import static org.junit.jupiter.api.Assertions.*;
class NativeRestartRuntimeAssemblyTest {
 static NativeRestartContract contract(){var b=PlannedMaintenanceStartupFactoryTest.B;return NativeRestartContract.fixedReviewedBuild(new CleanClosedRestartAssembly.Policy(b,NativeRestartContract.PROTOCOL_IDENTITY,"explicit-test-restart",new QuarterRetentionPolicy.Configuration(b,QuarterRetentionPolicy.VERSION,"Asia/Taipei",QuarterRetentionPolicy.RULES,"explicit-test-quarter")),"https://test.example","test-audience");}
 @Test void shippedReleaseCannotBeProvisionedByFlagsOrPriorRamProof(){assertNull(NativeRestartCompiledRelease.current());assertThrows(IllegalStateException.class,NativeRestartCompiledRelease::require);assertThrows(NullPointerException.class,()->new NativeRestartRuntimeAssembly(null,null,Clock.systemUTC()));var p=contract().policy();assertThrows(RuntimeException.class,()->NativeRestartContract.fixedReviewedBuild(new CleanClosedRestartAssembly.Policy(p.binding(),"arbitrary-env-revision",p.approvalReference(),p.retention()),"https://test.example","test-audience"));}
 @Test void currentDurableCloseUsesOnlyNewRuntimeAndSameStage()throws Exception{
  var clock=JournaledNativeWriterTest.CLOCK;var m=new JournaledNativeWriterTest.Memory(DurableCleanHandoffAssessmentTest.closed());var reads=new AtomicInteger();var io=new NativeRestartRuntimeAssembly.IO(){public NativeSheetsModel.Book readNative(){reads.incrementAndGet();return m.snapshot();}public PlannedMaintenanceStartupFactory.Channels channels(){return PlannedMaintenanceStartupFactoryTest.channels(m);}};
  var runtime=new NativeRestartRuntimeAssembly(contract(),io,clock);var stage=runtime.staged();assertTrue(stage.inertRoutingSafe());runtime.resume();assertSame(stage,runtime.staged());assertEquals(NativeRestartRuntimeAssembly.Status.ATTACHED,runtime.status());assertFalse(runtime.gate().isOpen());var coordinator=new com.bridge.persistence.QuarterMaintenanceCoordinator(runtime.gate(),stage.lifecycle(),clock,()->true,()->{});coordinator.tick();assertTrue(stage.enabled());assertEquals(1,m.writes);assertThrows(RuntimeException.class,runtime::resume);runtime.close();
 }
 @Test void openOrUnprovenStateStaysMaintenanceNeverInitialWorkflow()throws Exception{
  var clock=JournaledNativeWriterTest.CLOCK;var m=JournaledNativeWriterTest.initial();int writes=m.writes;var io=new NativeRestartRuntimeAssembly.IO(){public NativeSheetsModel.Book readNative(){return m.snapshot();}public PlannedMaintenanceStartupFactory.Channels channels(){return PlannedMaintenanceStartupFactoryTest.channels(m);}};
  var runtime=new NativeRestartRuntimeAssembly(contract(),io,clock);assertThrows(RuntimeException.class,runtime::resume);assertEquals(NativeRestartRuntimeAssembly.Status.BLOCKED,runtime.status());assertEquals(writes,m.writes);assertFalse(runtime.staged().enabled());assertThrows(RuntimeException.class,runtime::resume);runtime.close();
 }
}
